<script setup>
import { router, useForm } from '@inertiajs/vue3';
defineProps({ rules:Array });
const form=useForm({course_count:2,percentage:10});
const submit=()=>form.post('/admin/rabais',{preserveScroll:true,onSuccess:()=>form.reset()});
const remove=rule=>confirm(`Supprimer le rabais de ${rule.percentage} % ?`)&&router.delete(`/admin/rabais/${rule.id}`,{preserveScroll:true});
</script>
<template><section class="grid gap-6 lg:grid-cols-[.7fr_1.3fr]"><div class="rounded-3xl bg-white p-6"><p class="text-xs font-bold uppercase tracking-[.18em] text-coral">Nouveau palier</p><h2 class="mt-2 font-serif text-3xl">Créer un rabais</h2><p class="mt-2 text-sm text-black/45">Calculé sur les cours de la même saison.</p><form @submit.prevent="submit" class="mt-6 space-y-4"><label class="block text-sm font-semibold">À partir de combien de cours ?<input v-model="form.course_count" type="number" min="2" class="mt-2 w-full rounded-xl border border-black/10 px-4 py-3 font-normal" /></label><label class="block text-sm font-semibold">Pourcentage<input v-model="form.percentage" type="number" min="0.01" max="100" step="0.01" class="mt-2 w-full rounded-xl border border-black/10 px-4 py-3 font-normal" /></label><p v-if="Object.keys(form.errors).length" class="text-xs text-red-600">{{ Object.values(form.errors)[0] }}</p><button class="w-full rounded-full bg-ink py-3.5 font-bold text-white">Ajouter</button></form></div><div class="overflow-hidden rounded-3xl bg-white"><div class="border-b border-black/5 px-6 py-5"><h2 class="font-serif text-2xl">Paliers de rabais</h2><p class="mt-1 text-xs text-black/45">{{ rules.length }} règles configurées</p></div><table v-if="rules.length" class="w-full text-left"><thead class="bg-[#f7f5f0] text-[11px] font-bold uppercase tracking-wider text-black/45"><tr><th class="px-6 py-4">Nombre de cours</th><th class="px-5 py-4">Rabais</th><th class="px-5 py-4">Application</th><th class="px-6 py-4 text-right">Actions</th></tr></thead><tbody class="divide-y divide-black/5"><tr v-for="rule in rules" :key="rule.id"><td class="px-6 py-5 font-bold">À partir de {{ rule.course_count }} cours</td><td class="px-5 py-5"><span class="rounded-full bg-green-50 px-3 py-1 font-bold text-green-700">{{ Number(rule.percentage) }} %</span></td><td class="px-5 py-5 text-sm text-black/45">Total cumulé de la saison</td><td class="px-6 py-5 text-right"><button @click="remove(rule)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500 ml-auto">×</button></td></tr></tbody></table><div v-else class="p-16 text-center text-black/40">Aucun rabais configuré.</div></div></section></template>
